INSERT INTO ativos (codigo,nome,categoria,tipo_subtipo,dono,usuario_principal,localizacao,ambiente,cid,criticidade,classificacao,dependencias,status,data_aquisicao,data_expiracao) VALUES ('IA-0001','ERP - SAP Business One','SaaS','Virtual','bruno.almeida@exemplo.com.br','paula.ribeiro@exemplo.com.br','Cloud SkyOne (Inovage)','Produção',ARRAY['Confidencialidade','Integridade','Disponibilidade'],'Alta','Restrito','Banco de dados SAP, módulo de contabilidade faturamento, notas fiscais eletrônicas e emissor fiscal centralizado.','Ativo','2023-01-01','2028-12-31') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ativos (codigo,nome,categoria,tipo_subtipo,dono,usuario_principal,localizacao,ambiente,cid,criticidade,classificacao,dependencias,status,data_aquisicao,data_expiracao) VALUES ('IA-0002','Estrutura SGSI','Processo','Processo','carla.souza@exemplo.com.br','ana.martins@exemplo.com.br','Escopo de atuação - App AURORA','Produção',ARRAY['Confidencialidade','Integridade','Disponibilidade'],'Alta','Restrito','Sistemas corporativos de conformidade, normativos internos da organização e diretrizes LGPD.','Ativo','2023-11-23',NULL) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0001', 'IA-0001', 'Falha do processo de Gestão de acessos SAP', 'Concessão indevida ou obsoleta de acessos ao sistema ERP, facilitando fraudes internas e alteração indevida de relatórios contábeis.', 3, 3, 'Alto', 'Sim', 'Multas regulatórias severas, distorções de estoque e impacto financeiro direto em fechamentos fiscais.', 'Mitigar', 'A.5.15 Controle de acesso', 'Controle formal de solicitação de acessos ao SAP por meio de chamados no ITSM com aprovação obrigatória do gerente imediato.', 'Workflow_Acessos_SAP_ITSM_v2.pdf', 'Preventivo', 'Manual', 'Diário', 'diego.ferreira@exemplo.com.br', 'Eficaz com Melhorias', ARRAY['Confidencialidade', 'Integridade'], 1, 2, 'Baixo', 'Falha do processo de Gestão de acessos', 'Falta de auditoria autônoma em tempo real para suspender usuários demitidos no mesmo dia.', '2025-05-10', '2025-11-10') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0002', 'IA-0001', 'SEGREGAÇÃO DE FUNÇÕES SAP B1 - Usuários com acessos conflitantes à regra de negócio', 'Acúmulo de atribuições operacionais incompatíveis (por exemplo, aprovar compras e efetuar pagamento de faturas) por uma única credencial.', 2, 3, 'Alto', 'Sim', 'Favorece fraudes internas, desvio de patrimônio e descumprimento das regras de compliance corporativo.', 'Mitigar', 'A.5.3 Segregação de funções', 'Desenho da matriz SOD (Segregation of Duties) determinando perfis incompatíveis no ERP.', 'Matriz_SOD_V1.xlsx', 'Preventivo', 'Manual', 'Diário', 'diego.ferreira@exemplo.com.br', 'Eficaz', ARRAY['Confidencialidade', 'Integridade'], 1, 2, 'Baixo', 'Ausência de segregação de função', 'Identificação periódica automatizada é manual ou inexistente em novos perfis criados sob demanda da equipe técnica.', '2025-04-12', '2025-10-12') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0003', 'IA-0001', 'PARÂMETROS DE SENHAS – BANCO DE DADOS SAP', 'Senhas administrativas do SGBD que hospedam o SAP fracas, imutáveis ou compartilhadas entre engenheiros de sustentação.', 2, 3, 'Alto', 'Sim', 'Vazamento total de dados de clientes, multas da ANPD e danos irreparáveis de imagem corporativa.', 'Mitigar', 'A.5.15 Controle de acesso', 'Revisão e alteração de senhas realizada sob chamada eventual.', 'N/A', 'Nenhum', 'Nenhum', 'Nenhum', 'diego.ferreira@exemplo.com.br', 'Ineficaz', ARRAY['Confidencialidade', 'Integridade', 'Disponibilidade'], 3, 9, 'Alto', 'Falha no processo de Gerenciamento de senhas', 'Banco de dados carece de regra sistêmica de bloqueio de força bruta ou rotação obrigatória automática nos servidores cloud.', '2025-02-15', '2025-08-15') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0004', 'IA-0001', 'SAP – ACESSOS PRIVILEGIADOS', 'Uso indiscriminado e irrestrito da credencial ''Manager / Super-user'' sem auditoria ou logs de atividades para tarefas de rotina.', 3, 3, 'Alto', 'Sim', 'Qualquer alteração crítica no sistema ocorre sem assinaturas digitais ou identificação individual inequívoca.', 'Mitigar', 'A.8.2 Direitos de acesso privilegiado', 'Exigência de contas individuais com privilégios específicos para equipe técnica. Contas compartilhadas suspensas para auditoria.', 'Ata_de_Revisao_Acessos_Especiais_2025.docx', 'Preventivo', 'Manual', 'Diário', 'ana.martins@exemplo.com.br', 'Eficaz', ARRAY['Confidencialidade', 'Integridade', 'Disponibilidade'], 1, 1, 'Baixo', 'Falha do processo de Gestão de acessos', 'Falta de trilha de auditoria e revisão constante.', '2025-05-18', '2025-11-18') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0005', 'IA-0001', 'GESTÃO DE MUDANÇAS – SAP B1', 'Correções, atualizações de scripts fiscais e parametrizações de impostos feitas direto no ambiente de produção sem testes de homologação.', 2, 3, 'Alto', 'Sim', 'Risco de indisponibilidade geral do ERP e parada de produção de faturamento e expedição de mercadorias.', 'Mitigar', 'A.8.32 Gestão de mudanças', 'Comitê de Controle de Mudanças (CAB) que avalia e aprova pacotes e deploys fora de horários operacionais críticos.', 'Politica_Mudancas_Sistemas_v1.pdf', 'Preventivo', 'Manual', 'Diário', 'ana.martins@exemplo.com.br', 'Eficaz', ARRAY['Integridade', 'Disponibilidade'], 1, 2, 'Baixo', 'Falha no processo de Gerenciamento de mudanças', 'A equipe de QA não assina relatórios formais de homologação em todos os módulos de suporte do SAP.', '2025-06-01', '2025-12-01') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0006', 'IA-0001', 'GESTÃO DE MUDANÇAS – POLITICA SAP', 'Inexistência de formalização oficial de uma Política de Mudanças para ERP, gerando decisões táticas e ad-hoc.', 2, 2, 'Médio', 'Sim', 'Gera inconsistência em auditoria e dificulta a obtenção de certificação ISO 27001.', 'Mitigar', 'A.8.32 Gestão de mudanças', 'Documento preliminar de Políticas de TI, no entanto carente de assinatura formal pela diretoria.', 'Diretrizes_Gerais_Mudanca.docx', 'Preventivo', 'Manual', 'Anual', 'ana.martins@exemplo.com.br', 'Eficaz', ARRAY['Confidencialidade', 'Integridade', 'Disponibilidade'], 2, 4, 'Médio', 'Falha no processo de Gerenciamento de mudanças', 'Politica aguardando comissão diretiva.', '2025-03-10', '2026-03-10') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0007', 'IA-0002', 'O SGSI não considera mudança climática', 'Falta de mapeamento de riscos decorrentes de extremos climáticos extremos sobre os datacenters de apoio e infraestrutura do SGSI.', 2, 2, 'Médio', 'Sim', 'Indisponibilidade física do back-office e infraestrutura se datacenters de apoio falharem simultaneamente.', 'Mitigar', 'A.5.1 Políticas para segurança da informação', 'Plano de continuidade de negócios prevendo redundância em nuvens distintas (Multicloud).', 'Plano_Continuidade_Negocio_v2.pdf', 'Preventivo', 'Manual', 'Anual', 'ana.martins@exemplo.com.br', 'Eficaz', ARRAY['Disponibilidade'], 1, 1, 1, 'Requisitos SGSI não estar em compliance com a ISO 27001:2022', 'A emenda com relação às mudanças climáticas (Amend 1:2024 de clima na ISO 27001) não foi explicitamente votada ou inserida na análise de contexto.', '2025-04-01', '2026-04-01') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO riscos (codigo,ativo_codigo,fator,descricao,probabilidade,impacto,nivel_inerente,impacto_financeiro,racional_impacto,tratamento_inerente,controle_codigo_iso,controle_descricao,controle_documentacao,controle_natureza,controle_categoria,controle_frequencia,controle_dono,controle_avaliacao,cid,prob_residual,impacto_residual,nivel_residual,gap_referencia,gap_descricao,ultima_revisao,proxima_revisao) VALUES ('RC-0008', 'IA-0002', 'Ausência de controles no SOA', 'Mapeamento incorreto ou incompleto de controles aplicáveis na Declaração de Aplicabilidade (SOA), omitindo temas obrigatórios organizacionais.', 2, 2, 'Médio', 'Sim', 'Detecção de Gaps graves em auditoria de certificação que levarão a não-conformidades maiores.', 'Mitigar', 'A.5.1 Políticas para segurança da informação', 'Recomposição do mapa SOA correlacionando com o SGSI total.', 'N/A', 'Nenhum', 'Nenhum', 'Anual', 'ana.martins@exemplo.com.br', 'Ineficaz', ARRAY['Confidencialidade', 'Integridade', 'Disponibilidade'], 2, 4, 'Médio', 'Requisitos SGSI não estar em compliance com a ISO 27001:2022', 'Falta de revisão independente externa.', '2025-05-15', '2026-05-15') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0001','RC-0001','IA-0001','SAP - Acesso Privilegiado','Usuários com nível de acesso elevado indevidos (perfil administrativo) identificados sem devida autorização formal assinada durante auditoria interna trimestral.',ARRAY['Infraestrutura','Compliance'],'Auditoria Interna (cláusula 9.2)','A.5.15 Controle de acesso','Menor','infraestrutura@exemplo.com.br','auditoria.interna@exemplo.com.br','2024-11-04','2025-02-03','Falha humana no processo manual de criação de novas credenciais e falta de auditoria ou triagem semestral nos perfis do SAP.','Remoção imediata dos perfis com privilégio excessivo de 3 usuários que haviam mudado de setor.','Estruturação de workflow automático de revogação de permissões sob mudança de cargo e integração de rotina automatizada de fechamento mensal no ERP.','Implementação de treinamento periódico sobre segurança da informação para gerentes de área na requisição de privilégios.','2025-03-04','ana.martins@exemplo.com.br','Capacitação obrigatória de 100% das lideranças em gestão de identidades corporativas.','Workflow com Agidesk ITSM implantado para formalizar os acessos e requisições temporárias.','Implementada','Implementada','Eficaz','https://aurora.exemplo.com.br/sites/AuroraIT/Compartilhados/Evidencia_Controle_Acesso_SAP.pdf','Ação de correção executada e devidamente testada pela auditoria interna na revisão de fevereiro.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0002','RC-0002','IA-0001','SAP - Segregação de Funções','Usuários no setor fiscal possuindo permissão simultânea de cadastrar fornecedor e solicitar pagamento de faturas, violando regras explícitas da matriz de segregação de funções.',ARRAY['Infraestrutura','Financeiro'],'Auditoria Interna (cláusula 9.2)','A.5.3 Segregação de funções','Menor','diego.ferreira@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-01-06','2025-03-03','A Matriz SOD anterior estava defasada e ignorava atualizações de pacotes e remanejamentos de pessoal no início do ano letivo fiscal.','Revogação imediata da permissão de faturamento dos operários do financeiro e vice-versa, dividindo as funções entre equipes distintas.','Atualizar a documentação da matriz de segregação de funções e parametrizar alertas de conflitos sistêmicos diretamente no SAP Business One.','Relatório de conformidade de perfis gerado mensalmente e enviado por e-mail para a equipe de controle interno.','2025-02-11','ana.martins@exemplo.com.br','Parametrizar um job periódico que compare a base do SAP à planilha de cargos autorizados do RH.','Falta de tempo hábil para desenvolver script de automação delegou a revisão a uma rotina apenas manual.','Implementada','Implementada','Ineficaz','https://aurora.exemplo.com.br/sites/AuroraIT/Compartilhados/Matrix_SOD_Aprovada.xlsx','Apesar de implementada, a eficácia foi ineficaz porque em nova verificação o conflito voltou a ocorrer por conta de um chamado de urgência não mapeado.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0003','RC-0003','IA-0001','PARÂMETROS DE SENHAS – BANCO DE DADOS','Ausência de bloqueio de complexidade de senha na base MS SQL Server vinculada ao SAP, permitindo senhas óbvias.',ARRAY['Infraestrutura','Compliance'],'Auditoria Interna (cláusula 9.2)','A.5.15 Controle de acesso','Menor','diego.ferreira@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-04-15','2025-11-10','Utilização do MS SQL Server com autenticação mista e senhas de serviço compartilhadas para automações antigas de cobranças.','Alterar a senha do super-administrador ''sa'' do SQL Server para um valor de 24 caracteres aleatórios armazenado em cofre.','Migrar a autenticação dos usuários de banco de dados para Active Directory corporativo (AD integrado).','Criação de procedimento operacional sobre hardening de bancos de dados produtivos da organização.','2025-04-30','ana.martins@exemplo.com.br','Execução automatizada de script de auditoria de vulnerabilidade na base mensalmente.','Impacto no sistema de CRM legado impediu a alteração completa imediata de algumas senhas de serviço.','Aberto','Aberto','Parcial',NULL,'Aguardando migração definitiva programada para as próximas semanas.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0004','RC-0004','IA-0001','Usuários com acessos indevidos ao perfil ''Super-Usuário'' do SAP','Identificação de 5 credenciais ativas como superusuários pertencentes a ex-consultores externos que já concluíram o período de contrato de desenvolvimento.',ARRAY['Infraestrutura'],'Auditoria Interna (cláusula 9.2)','A.5.15 Controle de acesso','Menor','diego.ferreira@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-01-14','2025-02-28','Falha de comunicação entre o setor de contratos e o suporte técnico de TI para notificar o encerramento do contrato e pedir a desativação da credencial.','Inativação instantânea de todas as contas indevidas detectadas.','Estreitar rito de onboarding e offboarding de prestadores de serviços por meio do RH vinculando o período de vigência ao Active Directory.','Bloqueio automático de contas após 30 dias de inatividade no banco de dados corporativo.','2025-02-03','ana.martins@exemplo.com.br',NULL,NULL,'Implementada','Implementada','Eficaz','https://aurora.exemplo.com.br/sites/AuroraIT/Compartilhados/Relatorio_Inativacoes_SAP.pdf','Nenhuma vulnerabilidade foi explorada de fato; a correção mitigou o risco por total.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0005','RC-0005','IA-0001','GESTÃO DE MUDANÇAS – SAP B1','Criação de novos campos obrigatórios direto em produção para responder a novas regras fiscais de ICMS sem validação prévia de testes em QA.',ARRAY['Infraestrutura','Operações - Sustentação'],'Auditoria Interna (cláusula 9.2)','A.8.25 Ciclo de vida de desenvolvimento seguro','Menor','diego.ferreira@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-04-15','2025-05-26','Urgência de atendimento de portarias fiscais associada à indisponibilidade de ambiente de testes atualizado no servidor de QA.','Ajustar os metadados do SAP e homologar de forma retroativa o comportamento das regras fiscais no ambiente de QA.','Proibir alterações de infraestrutura ou metadados de bases de dados do SAP via banco de dados; todas as mudanças devem passar pelo painel de homologação.','Atualizar mensalmente a base de dados de QA com dados mascarados de produção para assegurar um ambiente confiável para testes operacionais.','2025-04-16','ana.martins@exemplo.com.br',NULL,NULL,'Implementada','Implementada','Eficaz','https://aurora.exemplo.com.br/sites/AuroraIT/Compartilhados/Ata_Homologacao_Filtro_Fiscal.pdf',NULL) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0006','RC-0006','IA-0001','GESTÃO DE MUDANÇAS – POLITICA SAP','A política formal de controle de mudanças no ERP SAP não possui controle de versão assinado nem aprovações do comitê de direção.',ARRAY['Infraestrutura','SGSI'],'Auditoria Interna (cláusula 9.2)','7.5 Informação documentada (criação, atualização, controle)','Menor','ana.martins@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-04-15','2025-09-30','Foco exclusivo na execução das mudanças técnicas em detrimento do processo de governança documental e formalização perante a direção.','Submeter rascunho da política de mudanças para votação oficial do conselho administrativo.','Instituir comitê de segurança da informação trimestral para acompanhar conformidade documental das políticas de controle.','Mapear todas as políticas necessárias para conformidade ISO 27001 por meio do mapa de aplicabilidade com prazos de revisão.','2025-05-21','ana.martins@exemplo.com.br',NULL,NULL,'Em andamento','Em andamento','Eficaz',NULL,'Aguardando reunião geral do conselho do SGSI para validação de assinatura final.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO ncs (codigo,risco_codigo,ativo_codigo,detalhe,descricao,processos,origem,clausula,tipo,dono_correcao,identificado_por,data_identificacao,data_encerramento,causa_raiz,correcao_imediata,acao_corretiva,acao_preventiva,data_proposta,dono_proposta,descricao_acao_preventiva,justificativa,status_correcao,status_preventiva,status_eficacia,link_evidencia,observacoes) VALUES ('NC-0007','RC-0007','IA-0002','O SGSI não considera mudança climática','Contexto externo do SGSI não documenta ou cita de que forma as mudanças de clima podem prejudicar a continuidade dos serviços prestados aos clientes do sistema.',ARRAY['SGSI','Compliance'],'Auditoria Externa / Certificação','4.1 Compreender a organização e seu contexto','Menor','ana.martins@exemplo.com.br','auditoria.interna@exemplo.com.br','2025-04-07','2025-12-05','Auditando sistema com base na revisão antiga da norma ISO 27001:2013 sem incorporar a emenda publicada em 2024 de alterações climáticas.','Inserir análise do impacto do clima no Manual do SGSI e na Matriz SWOT da organização.','Realizar transição total e formalizada de conformidade do manual corporativo para a versão de 2022 (ISO/IEC 27001:2022 + Amend 1).','Participação direta em grupos profissionais de conformidade para prever novas portarias e adequações normativas de forma ágil.','2025-08-04','ana.martins@exemplo.com.br',NULL,NULL,'Aberto','Aberto','Não Avaliado',NULL,NULL) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0001','RC-0001','NC-0001','A.5.16','Agidesk ITSM','Ferramenta','Auditoria','Estabelecer o painel Agidesk ITSM como única via para solicitações formais de acesso ao SAP. Todo chamado fechado deve persistir o PDF com a autorização assinada da gerência solicitante.','diego.ferreira@exemplo.com.br','Implementado','2024-01-30','2025-02-03','https://aurora.exemplo.com.br/sites/EquipeInfra/Processos/Evidencias/Job_Agidesk.pdf','ana.martins@exemplo.com.br','Implementado com sucesso. Trilha de auditoria das solicitações SAP agora 100% integradas.','O uso de uma ferramenta centralizada de ITSM mitiga em mais de 90% erros humanos de liberação ad-hoc por mensagens informais (WhatsApp ou Slack).') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0002','RC-0002','NC-0002','A.5.3','Revisão de acessos','Processo','Auditoria','Promover uma dinâmica de revisão abrangente na base de usuários com os diretores de área para expurgar credenciais legadas, revogar heranças indevidas de acessos e criar novos perfis de restrição.','diego.ferreira@exemplo.com.br','Implementado','2025-02-28','2025-03-14','https://aurora.exemplo.com.br/sites/EquipeInfra/Processos/Evidencias/Ata_Revisao_SOD_Marco.pdf','ana.martins@exemplo.com.br','Processo executado. Contudo, há necessidade de sistemas com inteligência de cruzamento de dados para evitar reincidências de perfis customizados ad-hoc.','Os supervisores não prestam atenção em termos complexos da TI. A matriz SOD deve ser expressa em termos de fluxos de negócio amigáveis (Comprar, Pagar, Vender, Faturar).') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0003','RC-0003','NC-0003','A.5.15','Complexidade de senhas SAP (Inovage)','Procedimento','Auditoria','Formalizar o guia técnico de configuração de senhas obrigando caracteres especiais, expiração em 60 dias e impedindo a reutilização das 5 últimas senhas cadastradas.','diego.ferreira@exemplo.com.br','Atrasado','2025-09-15','2025-11-03',NULL,NULL,'Falta aprovação técnica da equipe Inovage de suporte para avaliar se a quebra de conexões afetará a emissão automática de faturamento fiscal da SkyOne.','Hardening de banco de dados deve ser executado com muito critério de teste sob laboratório para não acarretar prejuízo em processos de venda urgentes.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0004','RC-0004','NC-0004','A.5.15','Super-Usuário do SAP B1 - Monitoramento e Políticas','Processo','Auditoria','Estabelecer uma rotina mensal de revisão onde a equipe técnica apresenta as atividades e auditoria de log do usuário de suporte central ''Manager'' para o comitê consultivo corporativo.','diego.ferreira@exemplo.com.br','Implementado','2025-02-03','2025-02-28','https://aurora.exemplo.com.br/sites/EquipeInfra/Evidencias/Super_User_Ata.pdf','ana.martins@exemplo.com.br','Rotina instituída. O relatório agora é emitido sob script e aponta divergências diretamente no e-mail do DPO.',NULL) ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0005','RC-0005','NC-0005','A.8.25','GESTÃO DE MUDANÇAS – SAP B1 - Estruturação de QA','Processo','Auditoria','Desenvolver ambiente isolado de QA no servidor de cloud e estabelecer a obrigatoriedade da assinatura da área demandante atestando conformidade funcional e de cálculos de ICMS antes do release principal.','diego.ferreira@exemplo.com.br','Implementado','2025-04-15','2025-05-26','https://aurora.exemplo.com.br/sites/EquipeInfra/Mudancas/Procedimento_QA.pdf','ana.martins@exemplo.com.br','Finalizado. Os problemas funcionais com novas portarias contábeis caíram a zero nos últimos deploys.','Nunca confie em testes parciais conduzidos pelo próprio programador que codificou a parametrização. O olhar de QA independente economiza tempo substancial de debug.') ON CONFLICT (codigo) DO NOTHING;
INSERT INTO planos (codigo,risco_codigo,nc_codigo,secao_iso,nome,tipo,origem,descricao,responsavel,status,data_inicio,data_fim,link_evidencia,verificado_por,notas,licoes_aprendidas) VALUES ('PA-0006','RC-0006','NC-0006','7.5','GESTÃO DE MUDANÇAS – POLITICA SAP - Assinaturas','Política','Auditoria','Reunir o conselho técnico de segurança da informação e submeter a versão revisada definitiva da política, regulamentando o tráfego de deploys de banco de dados e obtendo as rubricas legais.','ana.martins@exemplo.com.br','Em andamento','2025-09-19','2025-09-30',NULL,NULL,'Aguardando homologação documental para publicar no canal integrado de políticas organizacionais do SGSI.',NULL) ON CONFLICT (codigo) DO NOTHING;
